import{_ as a,a as n}from"./chunks/asc_copy_gm2ub_highdim_split.CZCdQ_8L.js";import{_ as p,a as c}from"./chunks/asc_copy_gm2ub_align_normal_padding.ChJildQu.js";import{_ as l,a as t,b as e}from"./chunks/iter_bit.Xy_E8irn.js";import{_ as o,o as i,a as d,b as _}from"./app.B47EjQll.js";const r="/ascendc.github.io/assets/mem_vec_c.B5-TByQ3.png",m="/ascendc.github.io/assets/db_iter_c.-9hCubc_.png",h="/ascendc.github.io/assets/iter2_exp_c.DWR30Smr.png",g="/ascendc.github.io/assets/db_stride_c.GsMgmQXo.png",w="/ascendc.github.io/assets/iter_rw_c.C7PMdg11.png",u="/ascendc.github.io/assets/rep_cont_c.8O7pgdEj.png",b="/ascendc.github.io/assets/rep_discont_c.Bz2elCRL.png",v="/ascendc.github.io/assets/rep_repeat_c.CAtaA_Bw.png",k="/ascendc.github.io/assets/rep_partial_c.BTfctt_4.png",y="/ascendc.github.io/assets/multi_iter_c.DiSAJzON.png",f="/ascendc.github.io/assets/mask_op_c.Qx4ESnpl.png",N=JSON.parse('{"title":"","description":"","frontmatter":{"breadcrumbs":[{"text":"Ascend C算子开发指南","link":"/guide/getting_started/ascend_c_overview_and_learning_path"},{"text":"编程指南","link":"/guide/programming_guide/programming_guide"},{"text":"编程模型","link":"/guide/programming_guide/programming_model/programming_model"},{"text":"AI Core SIMD编程","link":"/guide/programming_guide/programming_model/ai_core_simd_programming/ai_core_simd_programming"},{"text":"基于指针的C语言编程","link":"/guide/programming_guide/programming_model/ai_core_simd_programming/c_pointer_programming/c_pointer_programming"},{"text":"Memory矢量计算编程","link":"/guide/programming_guide/programming_model/ai_core_simd_programming/c_pointer_programming/memory_vector_computation"}]},"headers":[],"relativePath":"guide/programming_guide/programming_model/ai_core_simd_programming/c_pointer_programming/memory_vector_computation.md","filePath":"guide/programming_guide/programming_model/ai_core_simd_programming/c_pointer_programming/memory_vector_computation.md","outlineHeaders":[{"level":2,"title":"Memory矢量编程的基本步骤","slug":"Memory矢量编程的基本步骤","link":"#Memory矢量编程的基本步骤"},{"level":2,"title":"Memory矢量计算内存管理","slug":"Memory矢量计算内存管理","link":"#Memory矢量计算内存管理"},{"level":2,"title":"Memory数据搬运","slug":"Memory数据搬运","link":"#Memory数据搬运"},{"level":2,"title":"Memory数据计算","slug":"Memory数据计算","link":"#Memory数据计算"},{"level":3,"title":"高维切分计算","slug":"高维切分计算","link":"#高维切分计算"},{"level":4,"title":"迭代控制","slug":"迭代控制","link":"#迭代控制"},{"level":4,"title":"地址间隔配置","slug":"地址间隔配置","link":"#地址间隔配置"},{"level":4,"title":"掩码设置","slug":"掩码设置","link":"#掩码设置"},{"level":3,"title":"连续计算","slug":"连续计算","link":"#连续计算"},{"level":2,"title":"Memory矢量计算同步控制","slug":"Memory矢量计算同步控制","link":"#Memory矢量计算同步控制"},{"level":2,"title":"Memory矢量计算示例","slug":"Memory矢量计算示例","link":"#Memory矢量计算示例"}],"lastUpdated":1793871089000}'),B={name:"guide/programming_guide/programming_model/ai_core_simd_programming/c_pointer_programming/memory_vector_computation.md"};function M(C,s,A,x,P,U){return i(),d("div",null,[...s[0]||(s[0]=[_(`<div><article class="markdown-body"><h1>Memory矢量计算编程<span id="ZH-CN_TOPIC_0000002600000002"></span></h1><p>本文介绍基于Unified Buffer（UB）的Ascend C矢量计算开发方法，该计算能力简称Memory矢量计算编程，是Ascend C中最基础、应用最广泛的矢量编程方式。<a href="../../../language_extension/simd_builtin_keywords.html">NPU架构版本2201</a>原生支持完整的UB直接编程能力；<a href="../../../language_extension/simd_builtin_keywords.html">NPU架构版本3510</a>引入寄存器计算能力，推荐使用Reg矢量计算编程以获得更高性能。</p><h2 id="Memory矢量编程的基本步骤">Memory矢量编程的基本步骤<a class="header-anchor" href="#Memory矢量编程的基本步骤">​</a></h2><p>Memory矢量计算的标准数据流分为数据搬入、计算、数据搬出三个阶段，完整流程如下：</p><ol><li>通过DMA将数据从全局内存搬运至本地内存；</li><li>进行矢量计算；</li><li>计算完成后，通过DMA将结果从本地内存搬运回全局内存（Global Memory）。</li></ol><h2 id="Memory矢量计算内存管理">Memory矢量计算内存管理<a class="header-anchor" href="#Memory矢量计算内存管理">​</a></h2><p>Memory矢量计算依托本地内存中的UB完成运算，开发者需先将输入数据搬运至UB，再调用矢量计算指令执行计算。UB支持通过数组形式声明，分为静态申请和动态申请两种方式。</p><ul><li><p>静态申请：分配固定大小的内存空间，空间尺寸在编译阶段确定，运行时无法修改。</p><div class="code-block"><div class="code-header"><span class="lang-label">C</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="n">__global__</span><span class="w"> </span><span class="n">__vector__</span><span class="w"> </span><span class="kt">void</span><span class="w"> </span><span class="n">add_custom</span><span class="p">(...)</span>
<span class="p">{</span>
<span class="w">    </span><span class="k">constexpr</span><span class="w"> </span><span class="kt">uint32_t</span><span class="w"> </span><span class="n">ub_size</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">256</span><span class="p">;</span>
<span class="w">    </span><span class="n">__ubuf__</span><span class="w"> </span><span class="n">half</span><span class="w"> </span><span class="n">static_buffer</span><span class="p">[</span><span class="n">ub_size</span><span class="p">];</span><span class="w">  </span><span class="c1">// Compiler automatically aligns to 32 bytes</span>
<span class="p">}</span>
</code></pre></div></li><li><p>动态申请：用户需要通过&lt;&lt;&lt;&gt;&gt;&gt;中参数dynamic_ub_size指定动态内存的空间大小，其大小在运行期确定。</p><div class="code-block"><div class="code-header"><span class="lang-label">C</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="c1">// Device-side: declare dynamic shared memory</span>
<span class="n">__global__</span><span class="w"> </span><span class="n">__vector__</span><span class="w"> </span><span class="kt">void</span><span class="w"> </span><span class="n">add_custom</span><span class="p">(...)</span>
<span class="p">{</span>
<span class="w">    </span><span class="k">extern</span><span class="w"> </span><span class="n">__ubuf__</span><span class="w"> </span><span class="n">half</span><span class="w"> </span><span class="n">dynamic_buf</span><span class="p">[];</span>
<span class="w">    </span><span class="c1">// ...</span>
<span class="p">}</span>

<span class="c1">// Host-side: specify dynamic shared memory size via third parameter in &lt;&lt;&lt;&gt;&gt;&gt;</span>
<span class="kt">int32_t</span><span class="w"> </span><span class="n">main</span><span class="p">(</span><span class="kt">int</span><span class="w"> </span><span class="n">argc</span><span class="p">,</span><span class="w"> </span><span class="kt">char</span><span class="w"> </span><span class="k">const</span><span class="w"> </span><span class="o">*</span><span class="n">argv</span><span class="p">[])</span>
<span class="p">{</span>
<span class="w">    </span><span class="c1">// ...</span>
<span class="w">    </span><span class="kt">uint32_t</span><span class="w"> </span><span class="n">dyn_ubuf_size</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">1024</span><span class="w"> </span><span class="o">*</span><span class="w"> </span><span class="k">sizeof</span><span class="p">(</span><span class="kt">char</span><span class="p">);</span>
<span class="w">    </span><span class="n">add_custom</span><span class="o">&lt;&lt;&lt;</span><span class="n">blocks_per_grid</span><span class="p">,</span><span class="w"> </span><span class="n">threads_per_block</span><span class="p">,</span><span class="w"> </span><span class="n">dyn_ubuf_size</span><span class="p">,</span><span class="w"> </span><span class="n">stream</span><span class="o">&gt;&gt;&gt;</span><span class="p">(...);</span>
<span class="w">    </span><span class="c1">// ...</span>
<span class="p">}</span>
</code></pre></div></li></ul><h2 id="Memory数据搬运">Memory数据搬运<a class="header-anchor" href="#Memory数据搬运">​</a></h2><p>昇腾NPU提供多组专用接口，实现全局内存（GM）与UB之间的数据搬运，适配各类业务场景。为保障矢量计算效率，标准流程为：数据从GM搬运至UB完成计算，计算结果再从UB回写至GM，形成完整数据链路。 开发者可灵活配置参数，精准控制数据块数量、长度、地址间隔等属性，实现连续数据搬运与非连续（高维切分）数据搬运，充分发挥硬件搬运与计算的协同能力，提升矢量算子整体执行效率。</p><div data-filter="950"><p>本节以<a href="../../../language_extension/simd_builtin_keywords.html">NPU架构版本3510</a>为例介绍数据搬运接口。</p><table><thead><tr><th>数据通路</th><th>搬运模式</th><th>接口</th><th>适用场景</th></tr></thead><tbody><tr><td rowspan="2">Global Memory -&gt; UB</td><td>连续搬运</td><td><code>asc_copy_gm2ub(dst, src, size)</code><br><code>asc_copy_gm2ub_align(dst, src, size)</code></td><td>单段连续数据搬运，长度可非32B对齐</td></tr><tr><td>高维切分搬运</td><td><code>asc_copy_gm2ub(dst, src, burst_count, burst_len, src_stride, dst_stride)</code><br><code>asc_copy_gm2ub_align(dst, src, burst_count, burst_len, left_padding_num, right_padding_num, enable_constant_pad, l2_cache_mode, src_stride, dst_stride)</code></td><td>多块数据搬运，可配置块数、长度和首地址间隔；带<code>_align</code>的接口还可配置左右Padding、填充方式和L2 Cache策略</td></tr><tr><td rowspan="2">UB -&gt; Global Memory</td><td>连续搬运</td><td><code>asc_copy_ub2gm(dst, src, size)</code><br><code>asc_copy_ub2gm_align(dst, src, size)</code></td><td>单段连续数据搬运，长度可非32B对齐</td></tr><tr><td>高维切分搬运</td><td><code>asc_copy_ub2gm(dst, src, burst_count, burst_len, dst_stride, src_stride)</code><br><code>asc_copy_ub2gm_align(dst, src, burst_count, burst_len, l2_cache_mode, dst_stride, src_stride)</code></td><td>多块数据搬运，可配置块数、长度和首地址间隔；带<code>_align</code>的接口还可配置L2 Cache策略</td></tr></tbody></table><p>以上接口均要求UB起始地址32B对齐，搬运长度需满足数据类型的字节对齐要求。长度非32B整数倍时，GM向UB搬入会在目的UB中写入补齐数据，需为补齐后的写入范围预留空间；UB向GM搬出会按32B对齐范围读取源UB，需为读取范围预留合法空间，但仅将有效数据写入GM。</p><p><strong>连续搬运</strong>：若需将GM中连续地址的数据搬运至UB，仅需指定搬运数据的字节长度即可。下图搬运256B连续数据，以half类型为例，共128个元素，可调用<code>asc_copy_gm2ub</code>或<code>asc_copy_gm2ub_align</code>接口，以下两种调用方式任选其一：</p><img src="`+a+`" alt="连续搬运示意图" width="800"><div class="code-block"><div class="code-header"><span class="lang-label">C</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="kt">uint32_t</span><span class="w"> </span><span class="n">size</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">128</span><span class="w"> </span><span class="o">*</span><span class="w"> </span><span class="k">sizeof</span><span class="p">(</span><span class="n">half</span><span class="p">);</span>
<span class="c1">// Option 1</span>
<span class="n">asc_copy_gm2ub</span><span class="p">(</span><span class="n">dst_ub</span><span class="p">,</span><span class="w"> </span><span class="n">src_gm</span><span class="p">,</span><span class="w"> </span><span class="n">size</span><span class="p">);</span>
<span class="c1">// Option 2</span>
<span class="n">asc_copy_gm2ub_align</span><span class="p">(</span><span class="n">dst_ub</span><span class="p">,</span><span class="w"> </span><span class="n">src_gm</span><span class="p">,</span><span class="w"> </span><span class="n">size</span><span class="p">);</span>
</code></pre></div><div class="callout callout-note"><p class="callout-title"><svg class="callout-icon" viewBox="0 0 16 16" width="16" height="16"><path d="M0 8a8 8 0 1 1 16 0A8 8 0 0 1 0 8Zm8-6.5a6.5 6.5 0 1 0 0 13 6.5 6.5 0 0 0 0-13ZM6.5 7.75A.75.75 0 0 1 7.25 7h1a.75.75 0 0 1 .75.75v2.75h.25a.75.75 0 0 1 0 1.5h-2a.75.75 0 0 1 0-1.5h.25v-2h-.25a.75.75 0 0 1-.75-.75ZM8 6a1 1 0 1 1 0-2 1 1 0 0 1 0 2Z"></path></svg>说明</p><p>这些连续搬运接口主要为了提升用户数据搬运的易用性，由软件层面提供，底层通过高维切分接口实现。</p></div><p><strong>高维切分搬运</strong>：若需将GM中多段非连续数据搬入UB，可通过高维切分模式，配置数据块数量、单块长度、块间间隔等参数。下图搬运两个数据块，每块96B，两个数据块在GM上间隔为32B，在UB上间隔为64B。共搬运192B有效数据，目的UB至少需预留256B空间。</p><img src="`+n+`" alt="高维切分搬运示意图" width="800"><p><code>burst_len</code>、<code>src_stride</code>和<code>dst_stride</code>均以字节为单位，stride表示相邻数据块首地址的间隔。上图对应的参数如下：</p><div class="code-block"><div class="code-header"><span class="lang-label">C</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="kt">uint16_t</span><span class="w"> </span><span class="n">burst_count</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">2</span><span class="p">;</span>
<span class="kt">uint16_t</span><span class="w"> </span><span class="n">burst_len</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">96</span><span class="p">;</span>
<span class="c1">// Source burst starts are 96B + 32B apart.</span>
<span class="kt">uint16_t</span><span class="w"> </span><span class="n">src_stride</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">96</span><span class="w"> </span><span class="o">+</span><span class="w"> </span><span class="mi">32</span><span class="p">;</span>
<span class="c1">// Destination burst starts are 96B + 64B apart.</span>
<span class="kt">uint16_t</span><span class="w"> </span><span class="n">dst_stride</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">96</span><span class="w"> </span><span class="o">+</span><span class="w"> </span><span class="mi">64</span><span class="p">;</span>

<span class="n">asc_copy_gm2ub</span><span class="p">(</span><span class="n">dst_ub</span><span class="p">,</span><span class="w"> </span><span class="n">src_gm</span><span class="p">,</span><span class="w"> </span><span class="n">burst_count</span><span class="p">,</span><span class="w"> </span><span class="n">burst_len</span><span class="p">,</span><span class="w"> </span><span class="n">src_stride</span><span class="p">,</span><span class="w"> </span><span class="n">dst_stride</span><span class="p">);</span>
</code></pre></div><p><strong>高维切分搬运的对齐补齐与填充值配置</strong>：对齐补齐用于满足UB侧的32B对齐要求，填充值配置用于指定补齐区域写入的数值。普通接口按默认方式补齐非32B对齐的数据；需要显式配置左右Padding或填充方式时，可使用<code>asc_copy_gm2ub_align</code>的高维切分原型。UB起始地址需32B对齐，搬运长度需满足数据类型的字节对齐要求。</p><p>以搬运3个长度为48B的数据块为例，将<code>left_padding_num</code>和<code>right_padding_num</code>均设置为0，通过<code>dst_stride</code>选择补齐模式：</p><p>Compact模式下，将<code>dst_stride</code>设置为<code>burst_len</code>，即48B。三个数据块在UB中的起始偏移依次为0B、48B、96B，仅在144B有效数据的末尾补齐16B，目的UB至少需预留160B空间。</p><img src="`+p+'" alt="Compact模式32字节补齐示意图" width="800"><p>Normal模式下，将<code>dst_stride</code>设置为不等于<code>burst_len</code>且满足32B对齐的值，此例为64B。三个数据块在UB中的起始偏移依次为0B、64B、128B，每个数据块分别补齐16B，目的UB至少需预留192B空间。</p><img src="'+c+`" alt="Normal模式32字节补齐示意图" width="800"><p>以下示例中，<code>src_gm</code>、<code>dst_ub_compact</code>和<code>dst_ub_normal</code>均为half类型指针，两个目的UB分别预留上述空间。源数据连续排列，<code>src_stride</code>为48B；通过设置<code>enable_constant_pad</code>为<code>true</code>，将图中的补齐区域填充为half类型的0：</p><div class="code-block"><div class="code-header"><span class="lang-label">C</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="kt">uint32_t</span><span class="w"> </span><span class="n">burst_count</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">3</span><span class="p">;</span>
<span class="kt">uint32_t</span><span class="w"> </span><span class="n">burst_len</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">48</span><span class="p">;</span>
<span class="kt">uint64_t</span><span class="w"> </span><span class="n">src_stride</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">48</span><span class="p">;</span>
<span class="kt">uint8_t</span><span class="w"> </span><span class="n">left_padding_num</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">0</span><span class="p">;</span>
<span class="kt">uint8_t</span><span class="w"> </span><span class="n">right_padding_num</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">0</span><span class="p">;</span>

<span class="n">asc_set_copy_pad_val</span><span class="p">(</span><span class="n">static_cast</span><span class="o">&lt;</span><span class="n">half</span><span class="o">&gt;</span><span class="p">(</span><span class="mi">0</span><span class="p">));</span>
<span class="c1">// Compact: pad only the end of all three bursts, using at least 160B of UB.</span>
<span class="n">asc_copy_gm2ub_align</span><span class="p">(</span><span class="n">dst_ub_compact</span><span class="p">,</span><span class="w"> </span><span class="n">src_gm</span><span class="p">,</span><span class="w"> </span><span class="n">burst_count</span><span class="p">,</span><span class="w"> </span><span class="n">burst_len</span><span class="p">,</span>
<span class="w">                    </span><span class="n">left_padding_num</span><span class="p">,</span><span class="w"> </span><span class="n">right_padding_num</span><span class="p">,</span><span class="w"> </span><span class="nb">true</span><span class="p">,</span>
<span class="w">                    </span><span class="n">asc_load_l2_cache_mode</span><span class="o">::</span><span class="n">NORMAL_FIRST_VICTIM</span><span class="p">,</span><span class="w"> </span><span class="n">src_stride</span><span class="p">,</span><span class="w"> </span><span class="mi">48</span><span class="p">);</span>
<span class="c1">// Normal: pad each burst separately, using at least 192B of UB.</span>
<span class="n">asc_copy_gm2ub_align</span><span class="p">(</span><span class="n">dst_ub_normal</span><span class="p">,</span><span class="w"> </span><span class="n">src_gm</span><span class="p">,</span><span class="w"> </span><span class="n">burst_count</span><span class="p">,</span><span class="w"> </span><span class="n">burst_len</span><span class="p">,</span>
<span class="w">                    </span><span class="n">left_padding_num</span><span class="p">,</span><span class="w"> </span><span class="n">right_padding_num</span><span class="p">,</span><span class="w"> </span><span class="nb">true</span><span class="p">,</span>
<span class="w">                    </span><span class="n">asc_load_l2_cache_mode</span><span class="o">::</span><span class="n">NORMAL_FIRST_VICTIM</span><span class="p">,</span><span class="w"> </span><span class="n">src_stride</span><span class="p">,</span><span class="w"> </span><span class="mi">64</span><span class="p">);</span>
</code></pre></div><div class="callout callout-note"><p class="callout-title"><svg class="callout-icon" viewBox="0 0 16 16" width="16" height="16"><path d="M0 8a8 8 0 1 1 16 0A8 8 0 0 1 0 8Zm8-6.5a6.5 6.5 0 1 0 0 13 6.5 6.5 0 0 0 0-13ZM6.5 7.75A.75.75 0 0 1 7.25 7h1a.75.75 0 0 1 .75.75v2.75h.25a.75.75 0 0 1 0 1.5h-2a.75.75 0 0 1 0-1.5h.25v-2h-.25a.75.75 0 0 1-.75-.75ZM8 6a1 1 0 1 1 0-2 1 1 0 0 1 0 2Z"></path></svg>说明</p><p>Compact模式要求左右Padding均为0。Normal模式支持显式配置左右Padding。左右Padding均为0时，<code>enable_constant_pad</code>用于选择补齐区域的填充方式：为<code>true</code>时使用<code>asc_set_copy_pad_val</code>配置的值，为<code>false</code>时由硬件自动填充dummy假数据。左右Padding任一非0时，<code>enable_constant_pad</code>不生效，必须提前通过<a href="../../../../../api/SIMD-API/c_api/vector_datamove/asc_set_copy_pad_val.html">asc_set_copy_pad_val</a>配置填充值，左右Padding区域及右侧为32B对齐继续补齐的区域均使用该值。</p></div><p>以上为GM向UB的数据搬入逻辑，UB向GM的数据搬出可使用同系列接口实现。更多搬运接口说明可参考<a href="../../../../../api/SIMD-API/c_api/vector_datamove/vector_datamove.html">矢量数据搬运</a>。</p></div><h2 id="Memory数据计算">Memory数据计算<a class="header-anchor" href="#Memory数据计算">​</a></h2><p>Memory矢量计算包含连续计算和高维切分计算两种模式，同时支持掩码功能，可灵活控制参与计算的数据范围。 下文以加法接口为例，结合示意图说明两种模式的差异：连续计算用法简单，适用于一维张量的连续数据运算；高维切分计算灵活性更强，支持迭代运算与自定义地址间隔。开发者可根据业务场景按需选择。</p><img src="`+r+'" alt="Memory矢量计算模式示意图" width="800"><h3 id="高维切分计算">高维切分计算<a class="header-anchor" href="#高维切分计算">​</a></h3><p>高维切分能力主要是支持对计算接口设置<code>repeat_time</code>、<code>stride</code>和<code>mask</code>参数等，能精确控制指令的迭代执行、操作数的地址间隔和迭代内的掩码。</p><h4 id="迭代控制">迭代控制<a class="header-anchor" href="#迭代控制">​</a></h4><p>矢量计算单元单次迭代从UB读取8个连续的DataBlock（每个32字节），运算结果写入目的UB的8个对应DataBlock。</p><img src="'+m+'" alt="DataBlock迭代示意图" width="800"><p>若设置repeat_time（迭代次数）为2，单元将执行两轮迭代，总处理数据量为2 × 8 × 32字节 = 512字节；若数据类型为half（2字节 / 元素），则对应处理256个元素。</p><blockquote><p>📌 硬件约束：repeat_time取值范围为1~255，该约束对<a href="../../../language_extension/simd_builtin_keywords.html">NPU架构版本2201</a>、<a href="../../../language_extension/simd_builtin_keywords.html">NPU架构版本3510</a>全系列产品生效。</p></blockquote><img src="'+h+'" alt="2次迭代Exp计算" width="800"><h4 id="地址间隔配置">地址间隔配置<a class="header-anchor" href="#地址间隔配置">​</a></h4><p>矢量计算单元还支持带间隔的向量计算，通过<code>data_block_stride</code>（单次迭代内不同DataBlock间地址步长）和<code>repeat_stride</code>（相邻迭代间相同DataBlock的地址步长）来进行配置。<code>data_block_stride</code>是指单次迭代内不同DataBlock间地址步长。其取值不能超过UB大小限制。 连续计算，<code>data_block_stride</code>设置为1，对同一迭代内的8个DataBlock数据连续进行处理。 非连续计算，<code>data_block_stride</code>值大于1（如取2），同一迭代内不同DataBlock之间在读取数据时出现一个DataBlock的间隔，如下图所示。</p><img src="'+g+'" alt="data_block_stride示例" width="800"><blockquote><p>📌 若dst_block_stride == 0，等效于dst_block_stride = 1；若src_block_stride = 0，源操作数将始终复用第一个DataBlock。</p></blockquote><p>下图给出了单次迭代内源操作数与目的操作数在UB空间的读写示例。示例中源操作数的<code>data_block_stride</code>配置为2，表示单次迭代内不同DataBlock间地址步长为2个DataBlock；目的操作数的<code>data_block_stride</code>配置为1，表示单次迭代内地址连续。</p><img src="'+w+'" alt="单次迭代内源和目的操作数读写示例" width="800"><p>其中<strong>repeat_stride</strong>是指相邻迭代间相同DataBlock的地址步长，可通过设置<code>repeat_stride</code>来灵活控制不同的场景。</p><table><thead><tr><th>场景</th><th>repeat_stride取值</th><th>数据读取特点</th><th>适用场景</th></tr></thead><tbody><tr><td>连续计算</td><td>8</td><td>每轮迭代读取连续8个data_block，完成所有输入数据的计算</td><td><img src="'+u+'" alt="repeat_stride连续计算场景" width="600"></td></tr><tr><td>非连续计算</td><td>&gt;8 (如10)</td><td>相邻迭代间存在data_block间隔，地址不连续</td><td><img src="'+b+'" alt="repeat_stride非连续计算场景" width="600"></td></tr><tr><td>反复计算</td><td>0</td><td>对首个连续8个data_block反复读取和计算</td><td><img src="'+v+'" alt="repeat_stride反复计算场景" width="600"></td></tr><tr><td>部分重复计算</td><td>(0, 8)</td><td>相邻迭代间部分数据重复读取，一般场景不涉及</td><td><img src="'+k+'" alt="repeat_stride部分重复计算" width="600"></td></tr></tbody></table><p>当 <code>repeat_time</code>&gt;1 时，通过多次迭代完成计算。<code>repeat_stride</code> 表示相邻迭代间相同位置DataBlock的起始地址间隔（以DataBlock为单位）。例如 <code>repeat_stride</code> = 9 时，第一迭代的第1个DataBlock与第二迭代的第1个DataBlock间隔9个DataBlock。</p><img src="'+y+`" alt="多次迭代非连续场景示意图" width="800"><p>通过C风格接口配置<code>repeat_stride</code>和<code>data_block_stride</code>实现上述多次迭代功能。</p><div class="code-block"><div class="code-header"><span class="lang-label">C</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="c1">// In the above example with repeat interval of 9, the following configuration achieves the corresponding operation</span>
<span class="kt">uint8_t</span><span class="w"> </span><span class="n">repeat_time</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">1</span><span class="p">;</span>
<span class="kt">uint8_t</span><span class="w"> </span><span class="n">dst_block_stride</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">1</span><span class="p">;</span>
<span class="kt">uint8_t</span><span class="w"> </span><span class="n">src0_block_stride</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">1</span><span class="p">;</span>
<span class="kt">uint8_t</span><span class="w"> </span><span class="n">src1_block_stride</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">1</span><span class="p">;</span>
<span class="kt">uint8_t</span><span class="w"> </span><span class="n">dst_repeat_stride</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">9</span><span class="p">;</span>
<span class="kt">uint8_t</span><span class="w"> </span><span class="n">src0_repeat_stride</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">9</span><span class="p">;</span>
<span class="kt">uint8_t</span><span class="w"> </span><span class="n">src1_repeat_stride</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">9</span><span class="p">;</span>

<span class="n">asc_add</span><span class="p">(</span><span class="n">z</span><span class="p">,</span><span class="w"> </span><span class="n">x</span><span class="p">,</span><span class="w"> </span><span class="n">y</span><span class="p">,</span><span class="w"> </span><span class="n">repeat_time</span><span class="p">,</span><span class="w"> </span><span class="n">dst_block_stride</span><span class="p">,</span><span class="w"> </span><span class="n">src0_block_stride</span><span class="p">,</span><span class="w"> </span><span class="n">src1_block_stride</span><span class="p">,</span><span class="w"> </span><span class="n">dst_repeat_stride</span><span class="p">,</span><span class="w"> </span><span class="n">src0_repeat_stride</span><span class="p">,</span><span class="w"> </span><span class="n">src1_repeat_stride</span><span class="p">);</span>
</code></pre></div><h4 id="掩码设置">掩码设置<a class="header-anchor" href="#掩码设置">​</a></h4><p>针对同一个迭代中的数据，可以通过mask参数进行掩码操作来控制实际参与计算的个数。下图为进行Abs计算时通过mask逐比特模式按位控制哪些元素参与计算的示意图，1表示参与计算，0表示不参与计算。</p><img src="`+f+'" alt="掩码操作示意图" width="800"><p>每一位掩码对应数据中的一个元素的位置，通过有效位和无效位标记，实现对数据操作的精细化开关控制。 掩码为固定位宽数值，规则如下：有效位（值为1）代表对应元素参与计算，无效位（值为0）代表对应元素被屏蔽，不参与运算。</p><p>掩码设置提供了两种模式：Counter模式和Normal模式，Normal模式又包含连续模式、逐比特模式。 Counter模式适用于连续元素的计算场景。该模式下，掩码寄存器仅低64位有效，用于标识参与计算的元素总数；接口会自动忽略repeat_time，由系统根据元素数量自动匹配迭代次数。例如计算200个half类型元素时，受UB的32B对齐约束，需申请256个元素空间。此时使用Counter模式，可精确处理实际元素数量，避免多余计算。</p><img src="'+l+`" alt="Counter模式计算" width="600"><div class="code-block"><div class="code-header"><span class="lang-label">C</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="n">__ubuf__</span><span class="w"> </span><span class="n">half</span><span class="w"> </span><span class="n">dst_ub</span><span class="p">[</span><span class="mi">256</span><span class="p">];</span>
<span class="n">__ubuf__</span><span class="w"> </span><span class="n">half</span><span class="w"> </span><span class="n">src0_ub</span><span class="p">[</span><span class="mi">256</span><span class="p">];</span>
<span class="n">__ubuf__</span><span class="w"> </span><span class="n">half</span><span class="w"> </span><span class="n">src1_ub</span><span class="p">[</span><span class="mi">256</span><span class="p">];</span>
<span class="n">half</span><span class="w"> </span><span class="n">scalar_value</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mf">1.0</span><span class="p">;</span>
<span class="c1">// 1. Direct transfer processing (temporarily omitted)</span>
<span class="c1">// 2. Use high-dimensional segmentation API for computation</span>
<span class="c1">// 2.1 Set mask counter mode</span>
<span class="n">asc_set_mask_count</span><span class="p">();</span>
<span class="c1">// 2.2 Set Mask value to 200, indicating this computation processes 200 elements</span>
<span class="n">asc_set_vector_mask</span><span class="p">(</span><span class="mi">0</span><span class="p">,</span><span class="w"> </span><span class="n">static_cast</span><span class="o">&lt;</span><span class="kt">uint64_t</span><span class="o">&gt;</span><span class="p">(</span><span class="mi">200</span><span class="p">));</span><span class="w"> </span>
<span class="n">asc_add_scalar</span><span class="p">(</span><span class="n">dst_ub</span><span class="p">,</span><span class="w"> </span><span class="n">src0_ub</span><span class="p">,</span><span class="w"> </span><span class="n">scalar_value</span><span class="p">,</span><span class="w"> </span><span class="mi">1</span><span class="p">,</span><span class="w"> </span><span class="mi">1</span><span class="p">,</span><span class="w"> </span><span class="mi">1</span><span class="p">,</span><span class="w"> </span><span class="mi">1</span><span class="p">,</span><span class="w"> </span><span class="mi">8</span><span class="p">,</span><span class="w"> </span><span class="mi">8</span><span class="p">,</span><span class="w"> </span><span class="mi">8</span><span class="p">);</span>

<span class="c1">// 3. Default needs to reset to Normal mode, if subsequent still requires Counter mode then no need to reset to Normal mode</span>
<span class="n">asc_set_mask_normal</span><span class="p">();</span>
</code></pre></div><p>在Normal计算模式（默认模式，若未发生模式切换则无需重复配置）中，MASK寄存器会作为每个Repeat的掩码使用，mask参数可通过<code>asc_set_vector_mask</code>设置以控制单次迭代内参与计算的元素个数；只有高维切分支持此模式，在接口上区分为单次迭代内连续模式和单次迭代内逐bit模式。</p><ul><li><p>单次迭代内连续模式：表示前n个连续元素参与计算。取值范围和操作数的数据类型有关，数据类型不同，每次迭代内能够处理的元素个数最大值不同。</p><blockquote><p><strong>mask范围推导</strong>：Vector计算单元单次迭代固定处理32B × 8 block = 256B数据，因此mask最大值 = 256B / sizeof(DataType)。当操作数为16位（sizeof=2B）时，mask∈[0, 128]（256/2=128）；当操作数为32位（sizeof=4B）时，mask∈[0, 64]（256/4=64）；当操作数为64位（sizeof=8B）时，mask∈[0, 32]（256/8=32）。此推导规则可推广至其他数据类型（如bfloat16=16bit→mask上限128，fp32=32bit→mask上限64）。</p></blockquote><p>连续模式下，mask超出范围按照对应数据类型下mask最大值计算；mask = 0表示指令不会执行计算操作，该接口将被视为NOP（空操作）；若设置为负值可能产生未定义行为。</p><p>该模式下，可以指定单次迭代内计算前n个连续元素，其他数据不参与计算。例如：对src数据(shape(256)，数据类型为half)，该数据需通过2次迭代计算完（每次迭代计算128个元素），可通过设置mask = 100，表示第1次迭代计算[0, 99]范围的元素，第2次迭代计算[128, 227]范围的元素参与计算，其他元素不参与计算。</p><img src="`+t+`" alt="单次迭代内连续计算" width="600"><div class="code-block"><div class="code-header"><span class="lang-label">C</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="n">__ubuf__</span><span class="w"> </span><span class="n">half</span><span class="w"> </span><span class="n">dst_ub</span><span class="p">[</span><span class="mi">256</span><span class="p">];</span>
<span class="n">__ubuf__</span><span class="w"> </span><span class="n">half</span><span class="w"> </span><span class="n">src0_ub</span><span class="p">[</span><span class="mi">256</span><span class="p">];</span>
<span class="n">__ubuf__</span><span class="w"> </span><span class="n">half</span><span class="w"> </span><span class="n">src1_ub</span><span class="p">[</span><span class="mi">256</span><span class="p">];</span>
<span class="n">half</span><span class="w"> </span><span class="n">scalar_value</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mf">1.0</span><span class="p">;</span>

<span class="c1">// 1. Data transfer (temporarily omitted)</span>
<span class="c1">// 2. Use high-dimensional segmentation API for computation</span>
<span class="c1">// 2.1 Set mask Normal mode</span>
<span class="n">asc_set_mask_normal</span><span class="p">();</span>
<span class="c1">// 2.2 Set Mask value to 100, indicating single iteration computes first 100 elements</span>
<span class="n">asc_set_vector_mask</span><span class="p">(</span><span class="mi">0</span><span class="p">,</span><span class="w"> </span><span class="n">static_cast</span><span class="o">&lt;</span><span class="kt">uint64_t</span><span class="o">&gt;</span><span class="p">(</span><span class="mi">100</span><span class="p">));</span><span class="w"> </span>
<span class="n">asc_adds</span><span class="p">(</span><span class="n">dst_ub</span><span class="p">,</span><span class="w"> </span><span class="n">src0_ub</span><span class="p">,</span><span class="w"> </span><span class="n">scalar_value</span><span class="p">,</span><span class="w"> </span><span class="mi">2</span><span class="p">,</span><span class="w"> </span><span class="mi">1</span><span class="p">,</span><span class="w"> </span><span class="mi">1</span><span class="p">,</span><span class="w"> </span><span class="mi">1</span><span class="p">,</span><span class="w"> </span><span class="mi">8</span><span class="p">,</span><span class="w"> </span><span class="mi">8</span><span class="p">,</span><span class="w"> </span><span class="mi">8</span><span class="p">);</span>
</code></pre></div></li><li><p>单次迭代内逐比特模式：可以按位控制哪些元素参与计算，bit位的值为1表示参与计算，0表示不参与。分为maskHigh（高位mask）和maskLow（低位mask）。参数取值范围和操作数的数据类型有关，数据类型不同，每次迭代内能够处理的元素个数最大值不同。当操作数为16位时，maskLow、maskHigh∈[0, 264-1]，并且不同时为0；当操作数为32位时，maskHigh为0，maskLow∈(0, 264-1]；当操作数为64位时，maskHigh为0，maskLow∈(0, 232-1]。</p><p>该模式下，可以指定maskHigh和maskLow的值，来处理各种掩码操作。如需进行交错计算，则mask设置成01010101...或者10101010...模式即可。 以src数据(shape(256)，数据类型为half)为例，通过设置逐bit的掩码，可在单迭代中选取特定bit位的数值参与计算：</p><img src="`+e+`" alt="单次迭代内逐bit计算" width="600"><div class="code-block"><div class="code-header"><span class="lang-label">C</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="n">__ubuf__</span><span class="w"> </span><span class="n">half</span><span class="w"> </span><span class="n">dst_ub</span><span class="p">[</span><span class="mi">256</span><span class="p">];</span>
<span class="n">__ubuf__</span><span class="w"> </span><span class="n">half</span><span class="w"> </span><span class="n">src0_ub</span><span class="p">[</span><span class="mi">256</span><span class="p">];</span>
<span class="n">__ubuf__</span><span class="w"> </span><span class="n">half</span><span class="w"> </span><span class="n">src1_ub</span><span class="p">[</span><span class="mi">256</span><span class="p">];</span>

<span class="c1">// 1. Data transfer (temporarily omitted)</span>
<span class="c1">// 2. Use high-dimensional segmentation API for computation</span>
<span class="c1">// 2.1 Set mask Normal mode</span>
<span class="n">asc_set_mask_normal</span><span class="p">();</span>
<span class="c1">// 2.2 Set Mask to bit-wise mode (0101...), implement interleaved computation</span>
<span class="n">asc_set_vector_mask</span><span class="p">(</span><span class="mh">0x000000000000AAAA</span><span class="p">,</span><span class="w"> </span><span class="mh">0x0000000000000000</span><span class="p">);</span><span class="w"> </span>
<span class="n">asc_add</span><span class="p">(</span><span class="n">dst_ub</span><span class="p">,</span><span class="w"> </span><span class="n">src0_ub</span><span class="p">,</span><span class="w"> </span><span class="n">src1_ub</span><span class="p">,</span><span class="w"> </span><span class="mi">2</span><span class="p">,</span><span class="w"> </span><span class="mi">1</span><span class="p">,</span><span class="w"> </span><span class="mi">1</span><span class="p">,</span><span class="w"> </span><span class="mi">1</span><span class="p">,</span><span class="w"> </span><span class="mi">8</span><span class="p">,</span><span class="w"> </span><span class="mi">8</span><span class="p">,</span><span class="w"> </span><span class="mi">8</span><span class="p">);</span>
</code></pre></div></li></ul><h3 id="连续计算">连续计算<a class="header-anchor" href="#连续计算">​</a></h3><p>连续计算是软件层提供的简化接口，使用时无需配置掩码，可直接对源操作数中连续的N个数据执行运算，并将结果连续写入目的操作数，主要用于一维数据的批量计算。 以加法运算为例，如需对长度为4096的矢量执行加法，调用方式如下：</p><div class="code-block"><div class="code-header"><span class="lang-label">C</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="n">asc_add</span><span class="p">(</span><span class="n">z</span><span class="p">,</span><span class="w"> </span><span class="n">x</span><span class="p">,</span><span class="w"> </span><span class="n">y</span><span class="p">,</span><span class="w"> </span><span class="mi">4096</span><span class="p">);</span><span class="w"> </span><span class="c1">// 4096: number of consecutive elements involved in addition.</span>
</code></pre></div><h2 id="Memory矢量计算同步控制">Memory矢量计算同步控制<a class="header-anchor" href="#Memory矢量计算同步控制">​</a></h2><p>AI Core内部的MTE2搬运单元、矢量计算单元等均为异步并行运行，多个单元读写同一块存储资源时会产生数据依赖。因此Memory矢量计算必须借助流水同步接口，保障流程正常执行。Memory矢量计算流程比矩阵计算更简洁，分为数据搬入、计算、数据搬出三个阶段，分别对应流水线PIPE_MTE2、PIPE_V、PIPE_MTE3，需通过核内同步接口约束执行顺序，保证流程串行执行。在<a href="../../../language_extension/simd_builtin_keywords.html">NPU架构版本3510</a>产品中，可使用<code>asc_lock</code>与<code>asc_unlock</code>接口实现三阶段的同步控制。</p><p>关于<code>asc_lock</code>/<code>asc_unlock</code>的同步原理，以及双缓冲场景中的数据依赖和Buffer复用，请参考<a href="../../../advanced_programming/advanced_kernel_programming/intra_core_sync/mutex_multi_pipeline_sync.html">基于Mutex实现多流水同步</a>。</p><p>以下为矢量加法的完整示例：</p><div class="code-block"><div class="code-header"><span class="lang-label">C</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="n">__global__</span><span class="w"> </span><span class="n">__vector__</span><span class="w"> </span><span class="kt">void</span><span class="w"> </span><span class="n">add_kernel</span><span class="p">(</span><span class="n">__gm__</span><span class="w"> </span><span class="kt">float</span><span class="o">*</span><span class="w"> </span><span class="n">x</span><span class="p">,</span><span class="w"> </span><span class="n">__gm__</span><span class="w"> </span><span class="kt">float</span><span class="o">*</span><span class="w"> </span><span class="n">y</span><span class="p">,</span><span class="w"> </span><span class="n">__gm__</span><span class="w"> </span><span class="kt">float</span><span class="o">*</span><span class="w"> </span><span class="n">z</span><span class="p">)</span>
<span class="p">{</span>
<span class="w">    </span><span class="kt">uint8_t</span><span class="w"> </span><span class="n">mutex_id</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">1</span><span class="p">;</span>
<span class="w">    </span><span class="c1">// ...</span>
<span class="w">    </span><span class="c1">// 1. Step 1: Data transfer in, execution pipeline is PIPE_MTE2</span>
<span class="w">    </span><span class="n">asc_lock</span><span class="p">(</span><span class="n">PIPE_MTE2</span><span class="p">,</span><span class="w"> </span><span class="n">mutex_id</span><span class="p">);</span>
<span class="w">    </span><span class="n">asc_copy_gm2ub_align</span><span class="p">(</span><span class="n">x_local</span><span class="p">,</span><span class="w"> </span><span class="n">x_gm</span><span class="p">,</span><span class="w"> </span><span class="mi">1</span><span class="p">,</span><span class="w"> </span><span class="mi">48</span><span class="w"> </span><span class="o">*</span><span class="w"> </span><span class="k">sizeof</span><span class="p">(</span><span class="n">half</span><span class="p">),</span><span class="w"> </span><span class="mi">0</span><span class="p">,</span><span class="w"> </span><span class="mi">0</span><span class="p">,</span><span class="w"> </span><span class="nb">false</span><span class="p">,</span><span class="w"> </span><span class="n">asc_load_l2_cache_mode</span><span class="o">::</span><span class="n">NORMAL_FIRST_VICTIM</span><span class="p">,</span><span class="w"> </span><span class="mi">0</span><span class="p">,</span><span class="w"> </span><span class="mi">0</span><span class="p">);</span>
<span class="w">    </span><span class="n">asc_copy_gm2ub_align</span><span class="p">(</span><span class="n">y_local</span><span class="p">,</span><span class="w"> </span><span class="n">y_gm</span><span class="p">,</span><span class="w"> </span><span class="mi">1</span><span class="p">,</span><span class="w"> </span><span class="mi">48</span><span class="w"> </span><span class="o">*</span><span class="w"> </span><span class="k">sizeof</span><span class="p">(</span><span class="n">half</span><span class="p">),</span><span class="w"> </span><span class="mi">0</span><span class="p">,</span><span class="w"> </span><span class="mi">0</span><span class="p">,</span><span class="w"> </span><span class="nb">false</span><span class="p">,</span><span class="w"> </span><span class="n">asc_load_l2_cache_mode</span><span class="o">::</span><span class="n">NORMAL_FIRST_VICTIM</span><span class="p">,</span><span class="w"> </span><span class="mi">0</span><span class="p">,</span><span class="w"> </span><span class="mi">0</span><span class="p">);</span>
<span class="w">    </span><span class="n">asc_unlock</span><span class="p">(</span><span class="n">PIPE_MTE2</span><span class="p">,</span><span class="w"> </span><span class="n">mutex_id</span><span class="p">);</span>

<span class="w">    </span><span class="c1">// 2. Step 2: Compute, execution pipeline is PIPE_V</span>
<span class="w">    </span><span class="n">asc_lock</span><span class="p">(</span><span class="n">PIPE_V</span><span class="p">,</span><span class="w"> </span><span class="n">mutex_id</span><span class="p">);</span>
<span class="w">    </span><span class="n">asc_add</span><span class="p">(</span><span class="n">z</span><span class="p">,</span><span class="w"> </span><span class="n">x</span><span class="p">,</span><span class="w"> </span><span class="n">y</span><span class="p">,</span><span class="w"> </span><span class="mi">4096</span><span class="p">);</span>
<span class="w">    </span><span class="n">asc_unlock</span><span class="p">(</span><span class="n">PIPE_V</span><span class="p">,</span><span class="w"> </span><span class="n">mutex_id</span><span class="p">);</span>
<span class="w">    </span>
<span class="w">    </span><span class="c1">// 3. Step 3: Data transfer out, execution pipeline is PIPE_MTE3</span>
<span class="w">    </span><span class="n">asc_lock</span><span class="p">(</span><span class="n">PIPE_MTE3</span><span class="p">,</span><span class="w"> </span><span class="n">mutex_id</span><span class="p">);</span>
<span class="w">    </span><span class="n">asc_copy_ub2gm_align</span><span class="p">(</span><span class="n">z_gm</span><span class="p">,</span><span class="w"> </span><span class="n">z_local</span><span class="p">,</span><span class="w"> </span><span class="mi">1</span><span class="p">,</span><span class="w"> </span><span class="mi">48</span><span class="w"> </span><span class="o">*</span><span class="w"> </span><span class="k">sizeof</span><span class="p">(</span><span class="kt">int8_t</span><span class="p">),</span><span class="w"> </span><span class="n">asc_store_l2_cache_mode</span><span class="o">::</span><span class="n">NORMAL_FIRST_VICTIM</span><span class="p">,</span><span class="w"> </span><span class="mi">0</span><span class="p">,</span><span class="w"> </span><span class="mi">0</span><span class="p">);</span>
<span class="w">    </span><span class="n">asc_unlock</span><span class="p">(</span><span class="n">PIPE_MTE3</span><span class="p">,</span><span class="w"> </span><span class="n">mutex_id</span><span class="p">);</span>
<span class="p">}</span>
</code></pre></div><h2 id="Memory矢量计算示例">Memory矢量计算示例<a class="header-anchor" href="#Memory矢量计算示例">​</a></h2><p>结合上文介绍的数据搬运、计算、同步能力，即可基于C语言开发完整的Memory矢量计算算子。完整工程示例可参考：<a href="https://gitcode.com/cann/asc-devkit/tree/master/examples/02_simd_c_api/00_introduction/01_add/c_api_delicacy_async_add">c_api_add样例</a>。</p></article></div>`,1)])])}const T=o(B,[["render",M]]);export{N as __pageData,T as default};
